-- Metadata-only educational fixture. Synthetic auth_subject UUIDs are NOT Auth accounts.
-- Originals/chunks/providers are intentionally absent. Re-runs never restore revoked ACLs
-- or overwrite role/budget/content changes made after the initial seed.


  ON CONFLICT DO NOTHING;

  ON CONFLICT DO NOTHING;


  ON CONFLICT DO NOTHING;

SELECT fixture.id::uuid, fixture.team_id::uuid, fixture.document_id::uuid,
  fixture.grantee_membership_id::uuid, fixture.granted_by_membership_id::uuid FROM (VALUES
  ('60000000-0000-4000-8000-000000000001', '30000000-0000-4000-8000-000000000001', '50000000-0000-4000-8000-000000000001', '40000000-0000-4000-8000-000000000004', '40000000-0000-4000-8000-000000000004'),
  ('60000000-0000-4000-8000-000000000002', '30000000-0000-4000-8000-000000000001', '50000000-0000-4000-8000-000000000002', '40000000-0000-4000-8000-000000000004', '40000000-0000-4000-8000-000000000004'),
  ('60000000-0000-4000-8000-000000000003', '30000000-0000-4000-8000-000000000002', '50000000-0000-4000-8000-000000000003', '40000000-0000-4000-8000-000000000005', '40000000-0000-4000-8000-000000000005')
) AS fixture(id, team_id, document_id, grantee_membership_id, granted_by_membership_id)
WHERE NOT EXISTS (SELECT 1 FROM app.document_grants existing WHERE existing.id = fixture.id::uuid)
ON CONFLICT DO NOTHING;
